final class CourierRateProvider
{
    public function __construct(
        private readonly HttpClientInterface $courierClient,
        private readonly LoggerInterface $logger,
    ) {
    }

    public function chargeFor(string $district, int $weightGrams): ?int
    {
        try {
            $data = $this->courierClient->request('GET', '/v1/rates', [
                'query' => ['district' => $district, 'weight' => $weightGrams],
            ])->toArray();

            return (int) $data['charge_cents'];
        } catch (ExceptionInterface $e) {
            $this->logger->warning('Courier rate unavailable', ['exception' => $e]);

            return null;   // the caller decides: a default charge, or "we'll confirm later"
        }
    }
}

public function __construct(
    private readonly HttpClientInterface $courierClient,
    private readonly SemaphoreFactory $semaphores,
) {
}

public function chargeFor(string $district, int $weightGrams): ?int
{
    // out of 20 workers, at most 5 may be talking to the courier at once
    $slot = $this->semaphores->createSemaphore('courier-api', 5, ttlInSecond: 10);

    if (!$slot->acquire()) {
        return null;   // compartment full: don't queue up, go back at once
    }

    try {
        return $this->fetchCharge($district, $weightGrams);
    } finally {
        $slot->release();
    }
}

