#[AsEventListener(event: KernelEvents::REQUEST, priority: 30)]
final class LoadSheddingListener
{
    private const SHEDDABLE = ['/api/search', '/api/recommendations', '/api/reports'];

    public function __construct(private readonly RateLimiterFactory $lowPriorityLimiter)
    {
    }

    public function __invoke(RequestEvent $event): void
    {
        $path = $event->getRequest()->getPathInfo();
        $sheddable = array_filter(self::SHEDDABLE, fn ($p) => str_starts_with($path, $p));
        if (!$event->isMainRequest() || [] === $sheddable) {
            return;   // checkout, payment, login: never shed
        }

        $limit = $this->lowPriorityLimiter->create('global')->consume();
        if ($limit->isAccepted()) {
            return;
        }

        $wait = max(1, $limit->getRetryAfter()->getTimestamp() - time());
        $event->setResponse(new JsonResponse(
            ['error' => 'busy', 'message' => 'Please try again shortly'],
            Response::HTTP_SERVICE_UNAVAILABLE,
            ['Retry-After' => (string) $wait],
        ));
    }
}

final class OverloadDetector
{
    public function __construct(
        #[Autowire(env: 'int:CPU_CORES')]
        private readonly int $cores,
    ) {
    }

    public function isOverloaded(): bool
    {
        // average number of tasks running or waiting for a CPU core, last minute
        return sys_getloadavg()[0] > 1.5 * $this->cores;
    }
}

#[AsEventListener(event: KernelEvents::REQUEST, priority: 30)]
final class LoadSheddingListener
{
    private const SHEDDABLE = ['/api/search', '/api/recommendations', '/api/reports'];

    public function __construct(
        private readonly RateLimiterFactory $lowPriorityLimiter,
        private readonly OverloadDetector $overload,
    ) {
    }

    public function __invoke(RequestEvent $event): void
    {
        $path = $event->getRequest()->getPathInfo();
        $sheddable = array_filter(self::SHEDDABLE, fn ($p) => str_starts_with($path, $p));
        if (!$event->isMainRequest() || [] === $sheddable) {
            return;   // checkout, payment, login: never shed
        }
        if (!$this->overload->isOverloaded()) {
            return;   // healthy server: no cap, serve everything
        }
        if (!$this->lowPriorityLimiter->create('global')->consume()->isAccepted()) {
            $event->setResponse(new JsonResponse(
                ['error' => 'busy'],
                Response::HTTP_SERVICE_UNAVAILABLE,
                ['Retry-After' => '2'],
            ));
        }
    }
}

