        'json' => ['amount' => $cents],
    ])->toArray();
}

final class CircuitBreaker
{
    public function __construct(
        private readonly CacheItemPoolInterface $cache,
        private readonly int $threshold = 5,
        private readonly int $openSeconds = 30,
    ) {
    }

    public function call(string $name, callable $action, callable $fallback): mixed
    {
        $item = $this->cache->getItem('breaker.'.$name);
        ['fails' => $fails, 'until' => $until] = $item->get() ?? ['fails' => 0, 'until' => 0];

        if ($until > time()) {
            return $fallback();                  // OPEN: the call is never made
        }

        try {
            $result = $action();                 // CLOSED, or the HALF-OPEN test
            $item->set(['fails' => 0, 'until' => 0]);
        } catch (TransportExceptionInterface|ServerExceptionInterface) { // network, 5xx only
            ++$fails;
            $until = $fails >= $this->threshold ? time() + $this->openSeconds : 0;
            $item->set(['fails' => $fails, 'until' => $until]);
            $result = $fallback();
        }

        $this->cache->save($item->expiresAfter(300));

        return $result;
    }
}

