final class BudgetedRetryStrategy implements RetryStrategyInterface
{
    public function __construct(
        private readonly RetryStrategyInterface $inner,
        private readonly RateLimiterFactory $retryBudgetLimiter,
    ) {
    }

    public function shouldRetry(
        AsyncContext $context,
        ?string $responseContent,
        ?TransportExceptionInterface $exception,
    ): ?bool {
        $should = $this->inner->shouldRetry($context, $responseContent, $exception);
        if (true !== $should) {
            return $should;
        }

        // is there a retry token left? If not, this call fails right here
        return $this->retryBudgetLimiter->create('payment')->consume()->isAccepted();
    }

    public function getDelay(
        AsyncContext $context,
        ?string $responseContent,
        ?TransportExceptionInterface $exception,
    ): int {
        return $this->inner->getDelay($context, $responseContent, $exception);
    }
}

public function forProduct(int $id): array
{
    $key = 'recs.last_good.'.$id;

    try {
        $items = $this->api->recommend($id);   // with its own timeout and breaker
        $this->cache->save(
            $this->cache->getItem($key)->set($items)->expiresAfter(86400),
        );

        return ['items' => $items, 'degraded' => false];
    } catch (ExceptionInterface $e) {
        $this->logger->warning('Recommendations down', ['exception' => $e]);
        $stale = $this->cache->getItem($key);

        return [
            'items' => $stale->isHit() ? $stale->get() : [],   // empty if there is none
            'degraded' => true,
        ];
    }
}

#[Route('/api/products/{id}', methods: ['GET'])]
public function show(Product $product, RecommendationProvider $recs): JsonResponse
{
    // core part: if this fails, the whole request fails, and that is correct
    $payload = ['product' => $this->normalizer->normalize($product)];

    // kill switch: when the ops team sets this key in the cache, the feature is off at once
    $off = $this->cache->getItem('kill.recommendations')->isHit();

    $payload['recommendations'] = $off
        ? ['items' => [], 'degraded' => true]
        : $recs->forProduct($product->getId());

    return $this->json($payload);
}

export function useProductPage(id: number) {
  const product = ref<Product | null>(null)
  const recs = ref<Recs>({ items: [], degraded: false })
  const failed = ref(false)

  async function load() {
    const [p, r] = await Promise.allSettled([
      api.product(id),
      api.recommendations(id),
    ])

    if (p.status === 'rejected') {
      failed.value = true          // the core part is gone: a real error
      return
    }
    product.value = p.value
    recs.value = r.status === 'fulfilled' ? r.value : { items: [], degraded: true }
  }

  return { product, recs, failed, load }
}

